select (to_regclass('public.user_mistakes') is not null) and (to_regclass('public.student_activity_events') is not null) and exists (select 1 from information_schema.columns where table_schema='public' and table_name='quiz_results' and column_name='completed_at') and not exists (select 1 from information_schema.columns where table_schema='public' and table_name='quiz_results' and column_name='created_at') as ok;
